import{_ as a,H as t,f as p,i as l}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"开篇词 | 商业思维是每个互联网人都应具备的升维能力","description":"","frontmatter":{},"headers":[{"level":2,"title":"为什么要和你分享这份“笔记”？","slug":"为什么要和你分享这份-笔记","link":"#为什么要和你分享这份-笔记","children":[]},{"level":2,"title":"“笔记”是怎么搭建商业思维体系的？","slug":"笔记-是怎么搭建商业思维体系的","link":"#笔记-是怎么搭建商业思维体系的","children":[{"level":3,"title":"导读篇","slug":"导读篇","link":"#导读篇","children":[]},{"level":3,"title":"基础知识","slug":"基础知识","link":"#基础知识","children":[]},{"level":3,"title":"商业升维","slug":"商业升维","link":"#商业升维","children":[]},{"level":3,"title":"技巧呈现","slug":"技巧呈现","link":"#技巧呈现","children":[]}]},{"level":2,"title":"写在最后","slug":"写在最后","link":"#写在最后","children":[]}],"relativePath":"商业思维案例笔记/开篇词｜商业思维是每个互联网人都应具备的升维能力.md","filePath":"商业思维案例笔记/开篇词｜商业思维是每个互联网人都应具备的升维能力.md","lastUpdated":1795554691000}'),i={name:"商业思维案例笔记/开篇词｜商业思维是每个互联网人都应具备的升维能力.md"};function r(n,e,o,h,s,_){return t(),p("div",null,[...e[0]||(e[0]=[l('<h1 id="开篇词-商业思维是每个互联网人都应具备的升维能力" tabindex="-1">开篇词 | 商业思维是每个互联网人都应具备的升维能力 <a class="header-anchor" href="#开篇词-商业思维是每个互联网人都应具备的升维能力" aria-label="Permalink to &quot;开篇词 | 商业思维是每个互联网人都应具备的升维能力&quot;">​</a></h1><p>你好，我是曹雄峰，很高兴能在极客时间与你相遇，和你分享我的业务认知、工作技巧以及职业感悟。</p><p>先做个简单的介绍。我先后做过产品、策略、运营、商务以及行业化的工作，用朋友的话说，在商业化这个领域，我算是既见过猪跑，又吃过猪肉。正因为对商业化领域懂得比较多，同事都喊我“曹老板”。</p><p>我进入互联网是一个很偶然的契机。大二的某一天，我参加了一个学长的毕业分享，整个内容就记得一句话：</p><ul><li>学长毕业拿到了某几个互联网大厂的 offer，年薪十多万，从事的是产品岗。</li></ul><p>可能现在毕业的同学觉得这个薪酬不算什么，但是在当时正常就业月薪 5k 左右的情况下，这个已经算非常高了。</p><p>从那之后，我就开始接触并学习互联网产品经理，梦想改变世界（毕业拿高薪），14 年毕业后加入了腾讯，现在在某一垂类公司负责商业运营的工作。</p><p>最开始我做的是用户产品，但是用户体验的不确定性让我无所适从（说实话，就是吵不过）。另一方面，对于用户体验极致化的观点我也并不认可，我认为用户的体验是相对的，也是有成本的，好的用户体验应该是在一定成本的框架下进行表达，如果体验极致，那给每个用户送钱就好。</p><p>偶然的一次机会，我接触了商业化相关的业务，才发现自己更感兴趣的是产品怎么赚钱以及如何赚更多的钱。第一次接触广告计费模式的演化历程，就被其激励相容的底层逻辑所吸引——怎么有这么完美的策略。相较于用户产品，商业产品在策略可量化以及数据可衡量上有更多的确定性，也在商业模式的组合创新上有更多的玩法。</p><p>在那之后，我就一直深耕商业化相关的工作了。先后负责过联盟广告以及应用商店广告等广告变现业务，又做过新的商业模式探索，再后来从广告转到游戏领域，做游戏联运，最后在腾讯的一段时间做广告行业化运营方向，几乎拿遍了公司所有业务奖项。这些经历中，有百亿盘子的商业化产品，当然，也有胎死腹中的项目。</p><h2 id="为什么要和你分享这份-笔记" tabindex="-1">为什么要和你分享这份“笔记”？ <a class="header-anchor" href="#为什么要和你分享这份-笔记" aria-label="Permalink to &quot;为什么要和你分享这份“笔记”？&quot;">​</a></h2><p>回顾过往的工作经历，我越来越庆幸当初的选择，不仅了解了不同产品的商业模式，也见识了水下互联网的灰产世界，让自己可以看到一个更加真实的互联网。同时也构建了用商业思维去判断和分析业务的多维视角，培养了快速理解业务、找到业务的破局点的能力。</p><p>我们置身于互联网这个“水大鱼大”的市场，如果不清楚商业思维，无异于鱼儿身处水中而不知何为水。</p><p>至于为什么要写这个专栏，我的初心有两个。</p><p>一个是和你一起为下一个阶段蓄力。虽然当前互联网被很多人看空，发展的速度也远不如前，并且正在经历着发展 24 年以来最大的一次裁员潮，但我依然坚信互联网是 21 世纪最伟大的发明和最庞大的产业，下一个时代的浪潮依旧是基于互联网衍生出来的新机会。</p><p>这段时间，恰好是我们学习基本原则、了解演进模式的好时间，待好的行业机会出现之后，顺势而动。我永远喜欢这么一句话：江湖无名，专心练剑。</p><p>还有一个，就是为你做一块敲开解商业世界大门的敲门砖。互联网这些年成功的商业模式有很多，失败的更是不计其数，单独看每一个都是很有意思的案例，也都是值得深挖的业务方向，但是如何让理解商业世界变得更快、更简单呢？</p><p>我带业务新人的时候一直在思考，有没有办法用一套简练的框架去分析和判断：一个产品商业模式的优劣，一个企业投资决策的脉络，一个业务风口起来的逻辑？怎么帮助一个不了解商业产品的人构建对于商业逻辑的理解，培养属于自己的商业思维呢？</p><p>别着急，后续的案例剖析会带给你这些问题的答案。</p><h2 id="笔记-是怎么搭建商业思维体系的" tabindex="-1">“笔记”是怎么搭建商业思维体系的？ <a class="header-anchor" href="#笔记-是怎么搭建商业思维体系的" aria-label="Permalink to &quot;“笔记”是怎么搭建商业思维体系的？&quot;">​</a></h2><p>为了帮助你更好地理解商业思维，掌握相应的思考方式和工具方法，我把课程整体拆解成了三大内容模块。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/1.png" alt=""></a></p><p>你会发现，三大内容模块其实是一个递进的关系，我们先通过基础知识模块来培养起商业化思考的习惯，了解商业。在夯实基础后，我们更进一步，学会站在一个更大的维度去看待商业世界。最后，我们进行一些高阶技巧的补充，一起来操盘全局的业务流程。</p><p>三大内容模块中，我又细分为了七个章节，每个章节都有各自的定位。</p><h3 id="导读篇" tabindex="-1">导读篇 <a class="header-anchor" href="#导读篇" aria-label="Permalink to &quot;导读篇&quot;">​</a></h3><p>第一个章节是导读篇，这里我只设置了一讲的内容。如果你对价值创造、抽象思考等等这样的名词还有些陌生，那么，我建议你一定不要略过这个“课前预习”的部分。它能帮你快速了解接下来每一章节的概要和关键内容，建立一个对商业思维的大致认知，为接下来的学习打下基础。</p><h3 id="基础知识" tabindex="-1">基础知识 <a class="header-anchor" href="#基础知识" aria-label="Permalink to &quot;基础知识&quot;">​</a></h3><p>价值创造：在这一章节，我们正式进入基础知识模块的学习。任何问题的解决都会带来商业的机会，而商业的空间则取决于其创造价值的大小，那什么样的创造才有价值呢？在价值创造这一章节，我会结合行业真实案例帮你去理解，行业的创新者是如何极大提升效率、利润和体验并降低成本，从而创造出惊人的财富的。</p><p>抽象思考：互联网产品千千万万，商业模式千奇百怪，那如何快速有效地去解构一个产品的结构和商业模式呢？这一章节，我会把商业分析中常用的工具，比如二八法则、二维解构、盐铁官营、结构分层以及时间刻度教给你，用这些工具带你掌握透过现象看本质的能力。</p><h3 id="商业升维" tabindex="-1">商业升维 <a class="header-anchor" href="#商业升维" aria-label="Permalink to &quot;商业升维&quot;">​</a></h3><p>非规律世界：在这一章节，我们正式进入商业升维模块。任何商业模式和商业策略并不是物理定律，不管是权限、环境、资本或者是供给的变化，都会对一个事情产生迥异的影响。我们需要认识到一切都是不确定的，因此这一章节我会重点对商业案例进行讲述，带你进一步去理解这个不确定的世界。</p><p>非共识机会：当一切都朝一个方向进行时，最好朝反方向深深看一眼。同理，在商业社会中，如果大家都朝一个方向前进，这个方向也一定会成为红海。勇于打破现状，挑战现实逻辑，寻找非共识的机会才会有更大的机会。因此，这一章节我会举不同领域的案例，为你展示如何突出重围。</p><p>终局思维：很多机会源于套利，很多产品红极一时，很多模式烟消云散。以时间的角度去理解商业的变化，用终局思维去推演模式的发展，则会更早理解业务长期问题，从而做出更好的选择。因此，在这一章节，我会带你去深入理解终局思维的概念，从多维度去帮你分析：为什么很多业务伴随时间发展就不行了呢？</p><h3 id="技巧呈现" tabindex="-1">技巧呈现 <a class="header-anchor" href="#技巧呈现" aria-label="Permalink to &quot;技巧呈现&quot;">​</a></h3><p>策略工具：最后我们进入技巧呈现模块。在我们学习了解构商业模式的不同角度，也拆解了不少行业案例的成败原因后，我会给你具体展示在操盘全局业务过程中常用到的三个工具。</p><p>这个模块有三个关键词：分析、呈现、节奏。</p><p>第一步，就是构建行业分析的能力，教会你快速构建对于一个陌生行业的认知并寻找市场机会；</p><p>第二步，则是教会你如何结构化地对上呈现关键结论和内容，尤其是偏研发背景的同学转型业务，这一点会非常重要，没有好的对上呈现则较难获取推进项目的资源；</p><p>最后一步，则是合理把控业务目标以及推进节奏，好的业务管理者一定是好的节奏大师，避免在指标用尽的情况下让团队陷入无尽的疲倦是一个很值得思考的问题。</p><h2 id="写在最后" tabindex="-1">写在最后 <a class="header-anchor" href="#写在最后" aria-label="Permalink to &quot;写在最后&quot;">​</a></h2><p>在最后，我希望你有一个轻松的心态和一个批判性的精神来学习这份“笔记”。为什么会有这么一个提醒？</p><p>先说轻松的心态，是因为我们往往不轻松。不论是面对外界环境的压力，还是应对工作中经常遇到的挑战，都需要我们持续补充和学习。所以，我们买了不少课，但打开率并不高，类似买书，买书如山倒，读书如抽丝。看着买的课和书，读不完、学不动又是一重压力。</p><p>所以在整个课程内容上，我都是以“一个业务案例 + 一个或多个关键知识点”的方式输出，很多时候你可以当故事来看，不要有太多的压力。</p><p>至于批判性的精神呢，我也想借产品大神张小龙的一句话，“我说的都是错的”，来表达一下我的观点。</p><p>商业世界变化繁复，没有人可以保证自己说的全部都是对的。如同课程里面所说的，这是一个非规律世界，我希望你也可以以批判性的眼光来看这个课程所讲述的每一篇内容，更期待你可以给我提供更多的信息和反馈，充实我的认知和理解，一起进步。</p><p>商业思维是一门长期主义课程，它不仅需要我们在课堂之中用心学习，更需要保持一颗非常旺盛的好奇心去不断探索，把工作和生活中看到的现象和问题，用我们课程里讲的技巧去解构分析，通过大量的练习形成肌肉记忆。只有这样，商业思维才能真正成为你的底层能力。</p><p>最后的最后，我也特别想听听你的声音，你对这门课有怎样的期待？或者你现在有哪些问题？又对身边发生的哪些商业故事感兴趣呢？都可以提出来。</p><p>欢迎你加入我们的读者交流群，我们下节课见！</p>',48)])])}const u=a(i,[["render",r]]);export{c as __pageData,u as default};
